function createScholarlyArticleSchema({ title, authors = [], year, journal, pmid, pmcid, doi }) {
  const formattedPmcid = pmcid ? (pmcid.toUpperCase().startsWith('PMC') ? pmcid.toUpperCase() : 'PMC' + pmcid) : null;
  const cleanPmid = pmid ? String(pmid).replace(/\D/g, '') : null;
  const sameAsUrls = [];
  if (formattedPmcid) sameAsUrls.push('https://www.ncbi.nlm.nih.gov/pmc/articles/' + formattedPmcid + '/');
  if (cleanPmid) sameAsUrls.push('https://pubmed.ncbi.nlm.nih.gov/' + cleanPmid + '/');
  if (doi) sameAsUrls.push('https://doi.org/' + doi.replace(/^https?:\/\/doi\.org\//, ''));
  const schema = { "@context": "https://schema.org", "@type": "ScholarlyArticle", "name": title };
  if (authors.length) schema.author = authors.map(n => ({ "@type": "Person", "name": n }));
  if (year) schema.datePublished = String(year);
  if (journal) schema.isPartOf = { "@type": "PublicationIssue", "isPartOf": { "@type": "Periodical", "name": journal } };
  if (sameAsUrls.length) schema.sameAs = sameAsUrls;
  return schema;
}
//

body.script:
//
(function() {
  "use strict";

  // 1. Theme Toggle
  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    if (document.body) document.body.classList.toggle("dark-mode", theme === "dark");
    try { localStorage.setItem("theme", theme); } catch (e) {}
    var btn = document.getElementById("theme-toggle");
    if (btn) {
      btn.textContent = theme === "dark" ? "☀️" : "🌙";
      btn.setAttribute("aria-label", theme === "dark" ? "Switch to light mode" : "Switch to dark mode");
    }
  }
  window.toggleTheme = function() {
    var cur = document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light";
    applyTheme(cur === "dark" ? "light" : "dark");
  };

  // Clean ?m=1 mobile parameter
  if (location.search === "?m=1") {
    history.replaceState(null, "", location.pathname + location.hash);
  }

  // 2. Consent-Gated Microsoft Clarity Loader
  var trackingLoaded = false;
  var CONSENT_KEY = "aginghealth_cookie_consent";
  function loadTracking() {
    if (trackingLoaded) return;
    trackingLoaded = true;
    ["keydown", "touchstart", "mousemove", "scroll"].forEach(function(ev) {
      window.removeEventListener(ev, loadTracking, { passive: true });
    });
    (function(c,l,a,r,i,t,y){
      c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
      t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
      y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
    })(window, document, "clarity", "script", "xcdxxf4miu");
  }
  function initLazyTracking() {
    ["keydown", "touchstart", "mousemove", "scroll"].forEach(function(ev) {
      window.addEventListener(ev, loadTracking, { passive: true });
    });
    setTimeout(loadTracking, 4500);
  }

  document.addEventListener("DOMContentLoaded", async function() {
    applyTheme(localStorage.getItem("theme") || "light");

    // Cookie Banner (Fixed ID match)
    var consent = localStorage.getItem(CONSENT_KEY);
    var banner = document.getElementById("cookie-banner");
    var acceptBtn = document.getElementById("accept-cookies");
    if (consent === "granted") {
      initLazyTracking();
    } else if (consent !== "denied" && banner) {
      banner.classList.add("is-visible");
    }
    if (acceptBtn) {
      acceptBtn.addEventListener("click", function() {
        localStorage.setItem(CONSENT_KEY, "granted");
        if (banner) banner.classList.remove("is-visible");
        loadTracking();
      });
    }

    // Share Bar URLs
    var postUrl = encodeURIComponent(window.location.href);
    var postTitle = encodeURIComponent(document.title);
    var fb = document.getElementById("share-fb");
    var bsky = document.getElementById("share-bsky");
    var pin = document.getElementById("share-pin");
    var li = document.getElementById("share-li");
    if (fb) fb.href = "https://www.facebook.com/sharer/sharer.php?u=" + postUrl;
    if (bsky) bsky.href = "https://bsky.app/intent/compose?text=" + postTitle + "%20" + postUrl;
    if (pin) pin.href = "https://pinterest.com/pin/create/button/?url=" + postUrl + "&description=" + postTitle;
    if (li) li.href = "https://www.linkedin.com/sharing/share-offsite/?url=" + postUrl;

    // Back to Top
    var topBtn = document.getElementById("back-to-top");
    if (topBtn) {
      var toggleTop = function() {
        topBtn.classList.toggle("is-visible", (window.scrollY || 0) > 250);
      };
      toggleTop();
      window.addEventListener("scroll", toggleTop, { passive: true });
      topBtn.addEventListener("click", function() {
        window.scrollTo({ top: 0, behavior: "smooth" });
      });
    }

    // Single Post Enhancements: TOC & Reading Time
    var post = document.getElementById("post-body");
    if (post) {
      if (!post.querySelector(".ah-auto-toc")) {
        var headings = post.querySelectorAll("h2, h3");
        if (headings.length >= 3) {
          var d = document.createElement("details");
          d.className = "ah-auto-toc";
          d.style.cssText = "background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 18px;margin:0 0 22px 0;";
          var summary = document.createElement("summary");
          summary.textContent = "In This Article (Table of Contents)";
          summary.style.cssText = "font-weight:700;cursor:pointer;";
          d.appendChild(summary);
          var list = document.createElement("ul");
          list.style.cssText = "margin:10px 0 0 0;padding-left:20px;line-height:1.65;";
          headings.forEach(function(el) {
            if (!el.id) el.id = el.textContent.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
            var item = document.createElement("li");
            if (el.tagName === "H3") item.style.marginLeft = "16px";
            var a = document.createElement("a");
            a.textContent = el.textContent.trim();
            a.href = "#" + el.id;
            item.appendChild(a);
            list.appendChild(item);
          });
          d.appendChild(list);
          post.prepend(d);
        }
      }
      var rt = document.getElementById("reading-time-output");
      if (rt) {
        var words = (post.innerText || "").trim().split(/\s+/).filter(Boolean).length;
        if (words > 0) rt.textContent = Math.max(1, Math.ceil(words / 200)) + " min read";
      }
    }

    // Single Feed Fetch for Both Sidebar Recent Posts & Related Articles
    var recentList = document.getElementById("recent-posts-list");
    var relatedGrid = document.getElementById("related-grid");
    if (recentList || relatedGrid) {
      try {
        var res = await fetch("/feeds/posts/default?alt=json&max-results=8");
        if (res.ok) {
          var data = await res.json();
          var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
          var currentUrl = location.href.replace(/\?m=1$/, "");

          if (recentList) {
            var frag = document.createDocumentFragment();
            entries.slice(0, 6).forEach(function(entry) {
              var altLink = (entry.link || []).find(function(l) { return l.rel === "alternate"; });
              if (!altLink) return;
              var liEl = document.createElement("li");
              liEl.style.cssText = "padding:8px 0;border-bottom:1px solid var(--border);line-height:1.45;";
              var aEl = document.createElement("a");
              aEl.href = altLink.href;
              aEl.textContent = (entry.title && entry.title.$t) ? entry.title.$t : "Untitled Article";
              liEl.appendChild(aEl);
              frag.appendChild(liEl);
            });
            recentList.appendChild(frag);
          }

          if (relatedGrid) {
            var html = "";
            var count = 0;
            for (var i = 0; i < entries.length && count < 4; i++) {
              var e = entries[i];
              var lObj = (e.link || []).find(function(l) { return l.rel === "alternate"; });
              var url = lObj ? lObj.href : "#";
              if (url === "#" || url.replace(/\?m=1$/, "") === currentUrl) continue;
              var title = (e.title && e.title.$t) ? e.title.$t : "Read Article";
              var img = (e.media$thumbnail && e.media$thumbnail.url) ? e.media$thumbnail.url.replace(/\/s\d+(-c)?\//, "/w400-h250-c/") : "";
              html += '<a class="related-card" href="' + url + '">' +
                (img ? '<img src="' + img + '" alt="' + title.replace(/"/g, "&quot;") + '" width="400" height="250" loading="lazy" />' : '') +
                '<span class="related-card-title">' + title + '</span></a>';
              count++;
            }
            relatedGrid.innerHTML = html || "<p>Explore more guides in the archive above.</p>";
          }
        }
      } catch (err) {
        console.warn("Feed fetch failed:", err);
      }
    }
  });
})();
//

//
(function () {
  "use strict";
  const DATABASE_PATH = "/p/glossary-data-hidden.html";
  const GLOSSARY_PAGE_PATH = "/p/glossary_36.html";
  const EXCLUDED = "a,h1,h2,h3,h4,h5,h6,button,pre,code,script,style,noscript,template,textarea,select,option,svg,math,[contenteditable]:not([contenteditable='false']),[data-no-glossary],#glossary-database,#glossary-container,.ah-article-glossary,.caption,.sidebar,.breadcrumb";

  function escapeRegExp(v) { return v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
  function canonicalKey(v) { return v.trim().toLowerCase().replace(/['’]/g, "").replace(/s\b/g, ""); }
  function slugifyTerm(t) { return t.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""); }

  function buildTermPattern(term) {
    const words = term.trim().replace(/['’]/g, "").split(/\s+/).map(function (w, i, arr) {
      if (/s$/i.test(w) && w.length > 3) return escapeRegExp(w.slice(0, -1)) + "['’]?s?";
      if (i === arr.length - 1 && w.length > 3 && !/[sxz]$/i.test(w)) return escapeRegExp(w) + "s?";
      return escapeRegExp(w);
    });
    return words.join("\\s+");
  }

  function isCurrentPage(url) {
    return location.origin === url.origin && location.pathname.replace(/\/+$/, "") === url.pathname.replace(/\/+$/, "");
  }

  async function linkGlossary() {
    const article = document.getElementById("post-body");
    if (!article || article.dataset.glossaryLinker) return;
    const databaseURL = new URL(DATABASE_PATH, location.origin);
    const glossaryURL = new URL(GLOSSARY_PAGE_PATH, location.origin);
    if (isCurrentPage(databaseURL) || isCurrentPage(glossaryURL)) return;

    article.dataset.glossaryLinker = "loading";
    try {
      const res = await fetch(databaseURL.href, { credentials: "same-origin" });
      if (!res.ok) throw new Error("HTTP " + res.status);
      const doc = new DOMParser().parseFromString(await res.text(), "text/html");
      const termsByKey = new Map();

      for (const entry of doc.querySelectorAll("#glossary-database .glossary-entry[data-term], .glossary-entry[data-term]")) {
        const term = (entry.getAttribute("data-term") || "").trim();
        if (!term) continue;
        const key = canonicalKey(term);
        if (termsByKey.has(key)) continue;
        const dest = new URL(glossaryURL.href);
        dest.hash = slugifyTerm(term);
        const def = (entry.getAttribute("data-definition") || "").trim();
        termsByKey.set(key, { term: term, pattern: buildTermPattern(term), url: dest.href, definition: def });
      }

      const terms = Array.from(termsByKey.values()).sort((a, b) => b.term.length - a.term.length);
      if (!terms.length) return;

      const regex = new RegExp("(^|[^\\p{L}\\p{N}_])(" + terms.map(i => i.pattern).join("|") + ")(?=$|[^\\p{L}\\p{N}_])", "giu");
      const linked = new Set();
      const walker = document.createTreeWalker(article, NodeFilter.SHOW_TEXT, {
        acceptNode: n => (!n.parentElement || !n.nodeValue.trim() || n.parentElement.closest(EXCLUDED)) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
      });

      const nodes = [];
      while (walker.nextNode()) nodes.push(walker.currentNode);

      for (const node of nodes) {
        if (!article.contains(node)) continue;
        const text = node.nodeValue;
        const frag = document.createDocumentFragment();
        let cursor = 0, changed = false, match;
        regex.lastIndex = 0;
        while ((match = regex.exec(text)) !== null) {
          const matchedText = match[2];
          const key = canonicalKey(matchedText);
          const item = termsByKey.get(key);
          if (!item || linked.has(key)) continue;
          const start = match.index + match[1].length;
          frag.appendChild(document.createTextNode(text.slice(cursor, start)));
          const a = document.createElement("a");
          a.className = "auto-glossary-link";
          a.setAttribute("data-term", item.term);
          a.href = item.url;
          a.title = item.definition ? item.term + ": " + item.definition : "View definition in Aging Health Glossary";
          a.textContent = matchedText;
          frag.appendChild(a);
          linked.add(key);
          cursor = start + matchedText.length;
          changed = true;
        }
        if (changed) {
          frag.appendChild(document.createTextNode(text.slice(cursor)));
          node.parentNode.replaceChild(frag, node);
        }
      }
      article.dataset.glossaryLinker = "done";
    } catch (e) {
      delete article.dataset.glossaryLinker;
      console.warn("Glossary linker:", e);
    }
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", linkGlossary, { once: true });
  else linkGlossary();
})();
//
